import { brand, needs } from './content.js';
export const Navbar = () => `<header><a class="brand" href="/" aria-label="Aura Visage Spa, início"><img class="brand-logo" src="/assets/logo-aura.jpg" width="150" height="150" alt="Aura Visage Spa — Identidade, estética e presença"></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menu</button><nav id="navigation" aria-label="Navegação principal"><a href="/#conceito">O AURA</a><a href="/#cuidados">Cuidados</a><a href="/#servicos">Serviços e valores</a><a href="/#contato">Encontre o AURA</a></nav><button class="button small" data-schedule>Agendar avaliação</button></header>`;
export const Hero = (campaign) => `<section class="hero" id="principal"><div class="hero-copy"><p class="eyebrow">${campaign ? 'UM CONVITE AURA · '+campaign.name : 'ESTÉTICA, AUTOCUIDADO & BEM-ESTAR'}</p><h1>${campaign ? campaign.title : 'Seu tempo de<br>cuidar de <em>você.</em>'}</h1><p>${campaign ? campaign.text : 'Uma pausa no mundo lá fora.<br>Um encontro com o que faz bem a você.'}</p><div class="actions"><button class="button" data-schedule>Agendar minha avaliação</button><a class="text-link" href="/#cuidados">Explorar os cuidados</a></div><span class="hero-foot">CUIDADO QUE RESPEITA A SUA INDIVIDUALIDADE</span></div><figure class="hero-image"><img src="/assets/fachada-aura.jpg" alt="Fachada do AURA Visage Spa com placa da marca e vegetação" width="361" height="640" fetchpriority="high"><figcaption><a href="https://www.instagram.com/auravisagespa/reel/DZoNGhORtBX/" target="_blank" rel="noopener noreferrer">Fachada do AURA · imagem do Instagram</a></figcaption><div class="image-note">O essencial<br>é se sentir <em>bem.</em></div></figure></section>`;
export const TreatmentCard = (item,index) => `<button class="treatment" data-treatment="${index}"><span class="card-top"><span>0${index+1}</span><span class="card-symbol" aria-hidden="true">${['◯','⌒','≋','∿','◌','✧','◯','⌒','✧'][index]}</span></span><h3>${item.name}</h3><p>${item.text}</p><span class="card-action">Conhecer o cuidado <span aria-hidden="true">+</span></span></button>`;
export const CTASection = () => `<section class="cta"><p class="eyebrow">SEU PRÓXIMO MOMENTO</p><h2>O primeiro passo pode<br>ser uma <em>conversa.</em></h2><p>Vamos encontrar o cuidado que faz sentido para você?</p><button class="button light" data-schedule>Quero cuidar de mim</button></section>`;
export const FAQ = () => `<section class="faq section" id="duvidas"><div><p class="eyebrow">ANTES DA SUA VISITA</p><h2>Como podemos ajudar?</h2></div><div>${[
 ['Preciso saber qual tratamento quero fazer?','Não é necessário conhecer nomes de procedimentos. Você pode começar escolhendo uma área de interesse e conversar com a equipe sobre as possibilidades.'],
 ['Como funciona o agendamento?','Você pode escolher um serviço e reservar pelo Trinks, seguindo as etapas até a confirmação. Se preferir ajuda, fale com a recepção pelo WhatsApp. Abrir uma conversa não reserva um horário.'],
 ['Qual é o valor dos tratamentos?','Veja uma seleção de serviços e valores nesta página. O catálogo completo e a disponibilidade ficam no Trinks. Confira o valor final antes de confirmar sua reserva.'],
 ['O cuidado é indicado para qualquer pessoa?','A adequação de cada atendimento depende de avaliação profissional. Converse diretamente com a equipe sobre condições de saúde; não envie informações sensíveis neste formulário.']
 ].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></section>`;
export const Footer = () => `<footer><a class="brand" href="/"><img class="brand-logo" src="/assets/logo-aura.jpg" width="150" height="150" alt="Aura Visage Spa — Identidade, estética e presença"></a><p>Autocuidado, com espaço para ser você.</p><div><a href="/#duvidas">Dúvidas frequentes</a><a href="https://www.instagram.com/auravisagespa/" target="_blank" rel="noopener noreferrer">Instagram</a><button class="plain" data-privacy>Privacidade</button></div><small>© ${new Date().getFullYear()} Aura Visage Spa</small></footer>`;
export const LeadForm = () => `<dialog id="lead-dialog" aria-labelledby="lead-title"><button class="close" data-close aria-label="Fechar formulário">×</button><p class="eyebrow">DO SEU JEITO</p><h2 id="lead-title">Comece por <em>você.</em></h2><div class="booking-options"><a class="button" href="https://www.trinks.com/aura-visage-spa-ltda/framebusca" target="_blank" rel="noopener noreferrer" data-booking>Reservar pelo Trinks ↗</a><p>Escolha o serviço, o profissional e um horário disponível.</p></div><h3>Prefere conversar com a recepção?</h3><p>Yasmin pode ajudar você pelo WhatsApp. Escolha seu interesse. Atendemos de terça a sábado, das 09h às 18h. O AURA confirma a disponibilidade em uma conversa.</p><form id="lead-form"><label>Seu nome<input name="name" autocomplete="given-name" maxlength="80" required></label><label>WhatsApp com DDD<input name="phone" type="tel" autocomplete="tel" inputmode="tel" placeholder="(11) 99999-9999" required maxlength="20" pattern="[+0-9 ()-]{10,20}"></label><div class="form-grid"><label>O que quer cuidar?<select name="interest">${needs.map(n=>`<option>${n.name}</option>`).join('')}</select></label><label>Período de preferência<select name="period"><option>Sem preferência</option><option>Manhã</option><option>Tarde</option></select></label></div><label class="check"><input type="checkbox" name="consent" required>Quero usar estas informações para preparar meu pedido de contato.</label><p class="form-note">${brand.whatsapp ? 'Ao continuar, você poderá enviar a mensagem no WhatsApp. O horário depende de confirmação.' : 'Demonstração: o número oficial do AURA ainda não foi informado. Seus dados não serão enviados ou armazenados.'}</p><button class="button" type="submit">${brand.whatsapp?'Continuar no WhatsApp':'Preparar meu pedido'}</button><p id="lead-status" role="status"></p><div id="lead-result" hidden><label>Mensagem preparada<textarea readonly rows="5"></textarea></label><button class="plain" type="button" id="copy-message">Copiar mensagem</button></div></form></dialog><dialog id="detail-dialog" aria-labelledby="detail-title"><button class="close" data-close aria-label="Fechar detalhes">×</button><p class="eyebrow">CUIDADOS AURA</p><h2 id="detail-title"></h2><p id="detail-text"></p><p class="form-note">Consulte valores e horários no catálogo ou fale com a recepção.</p><button class="button" id="detail-cta">Tenho interesse</button></dialog><dialog id="privacy-dialog" aria-labelledby="privacy-title"><button class="close" data-close aria-label="Fechar privacidade">×</button><h2 id="privacy-title">Sua privacidade</h2><p>Este site prepara uma mensagem no seu navegador. Nome e telefone não são salvos nem enviados a um servidor.</p><p>Não há cookies de publicidade, pixels ou scripts de analytics. Os eventos técnicos ficam apenas na memória da página, sem nome ou telefone.</p><p>O formulário abre o WhatsApp oficial do AURA, (11) 93301-6741, com uma mensagem preparada. O envio depende da sua ação no aplicativo. Para dúvidas sobre o atendimento e seus dados, fale com a recepção nesse número. Ao abrir o Trinks, o WhatsApp, o Instagram ou o Google Maps, você passa a utilizar os serviços e as políticas dessas plataformas.</p></dialog>`;

